namespace Infrastructure.Keycloak;

public class KeycloakOptions
{
    public const string SectionName = "Keycloak";

    /// <summary>Base URL of Keycloak, e.g. http://bbu-auth-keycloak:8080</summary>
    public string BaseUrl { get; set; } = "";

    /// <summary>Realm name, e.g. bbu</summary>
    public string Realm { get; set; } = "bbu";

    /// <summary>Client ID with service-account enabled and view-users role</summary>
    public string ClientId { get; set; } = "";

    /// <summary>Client secret generated by Keycloak</summary>
    public string ClientSecret { get; set; } = "";
}
